-- ----------------------------
-- Procedure structure for `account_Transaction`
-- ----------------------------
DROP PROCEDURE IF EXISTS `account_Transaction`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `account_Transaction`(IN `FromDate` date,IN `ToDate` date,IN `CompanyId` bigint,IN `accountYearId` bigint,IN `accountId` bigint)
Begin
select b.accountId,b.accountName as accountname,'1' as 'tableid',accountTransactionId as 'uniqueid',a.accountDate as accountdate,'Retail Sales' 
as 'description1',concat('As per Invoice No - ',salesBillDisplayNumber) as 'description2',
'1' as 'displayorder',round(amount,2) as 'debit', '' as 'credit',salesBillDisplayNumber as 'innerdisplayorder','1' as 'totaldisplayorder'
 from accounttransaction as a 
inner join account as b on b.accountId=a.accountRefId
inner join salesbill as c on a.tableDetailId=c.salesBillID
 where a.accountRefId=accountId and a.companyRefId=CompanyId and a.accountYearRefId=accountYearId and a.tableReference=1
and a.accountDate BETWEEN FromDate and ToDate and c.salesBillType=3 

UNION

select b.accountId,b.accountName as accountname,'1' as 'tableid',accountTransactionId as 'uniqueid',a.accountDate as accountdate,d.`name` 
as 'description1',concat('Cash sales invoice Number - ',salesBillDisplayNumber) as 'description2',
'1' as 'displayorder',round(amount,2) as 'debit', '' as 'credit',salesBillDisplayNumber as 'innerdisplayorder','1' as 'totaldisplayorder'
 from accounttransaction as a 
inner join account as b on b.accountId=a.accountRefId
inner join salesbill as c on a.tableDetailId=c.salesBillID
inner join customer as d on d.customerID=c.CustomerID
 where a.accountRefId=accountId and a.companyRefId=CompanyId and a.accountYearRefId=accountYearId and a.tableReference=1
and a.accountDate BETWEEN FromDate and ToDate and c.salesBillType=2 


UNION

select b.accountId,b.accountName as accountname,'1' as 'tableid',accountTransactionId as 'uniqueid',a.accountDate as accountdate,d.`name` 
as 'description1',concat('Advance amount as per Invoice No - ',salesBillDisplayNumber) as 'description2',
'1' as 'displayorder',round(amount,2) as 'debit', '' as 'credit','' as 'innerdisplayorder','1' as 'totaldisplayorder'
 from accounttransaction as a 
inner join account as b on b.accountId=a.accountRefId
inner join salesbill as c on a.tableDetailId=c.salesBillID
inner join customer as d on d.customerID=c.CustomerID
 where a.accountRefId=accountId and a.companyRefId=CompanyId and a.accountYearRefId=accountYearId and a.tableReference=1
and a.accountDate BETWEEN FromDate and ToDate and c.salesBillType=1

UNION

select b.accountId,b.accountName as accountname,'1' as 'tableid',accountTransactionId as 'uniqueid',a.accountDate as accountdate, e.`name` 
as 'description1',concat('For Invoice No - ',salesBillDisplayNumber,'(',c.modeDescription,')') as 'description2',
'1' as 'displayorder',round(amount,2) as 'debit', '' as 'credit','' as 'innerdisplayorder','2' as 'totaldisplayorder'
 from accounttransaction as a 
inner join account as b on b.accountId=a.accountRefId
inner join salespayment as c on a.tableDetailId=c.salesPaymentId
inner join salesbill as d on c.salesBillRefId=d.salesBillID
inner JOIN customer as e on e.customerID=c.customerRefId
 where a.accountRefId=accountId and a.companyRefId=CompanyId and a.accountYearRefId=accountYearId and a.tableReference=5
and a.accountDate BETWEEN FromDate and ToDate and c.salesBillRefId!=0


UNION

select b.accountId,b.accountName as accountname,'1' as 'tableid',accountTransactionId as 'uniqueid',a.accountDate as accountdate, e.`name` 
as 'description1',concat(c.billDescription,'(',c.modeDescription,')') as 'description2',
'1' as 'displayorder',round(amount,2) as 'debit', '' as 'credit','' as 'innerdisplayorder','2' as 'totaldisplayorder'
 from accounttransaction as a 
inner join account as b on b.accountId=a.accountRefId
inner join salespayment as c on a.tableDetailId=c.salesPaymentId
inner JOIN customer as e on e.customerID=c.customerRefId
 where a.accountRefId=accountId and a.companyRefId=CompanyId and a.accountYearRefId=accountYearId and a.tableReference=5
and a.accountDate BETWEEN FromDate and ToDate and c.salesBillRefId=0


UNION

select b.accountId,b.accountName as accountname,'1' as 'tableid',accountTransactionId as 'uniqueid',a.accountDate as accountdate,'Retail purchase' 
as 'description1',concat('As per Invoice No - ',purchaseBillDisplayNumber) as 'description2',
'1' as 'displayorder','' as 'debit', round(amount,2) as 'credit',purchaseBillDisplayNumber as 'innerdisplayorder','3' as 'totaldisplayorder'
 from accounttransaction as a 
inner join account as b on b.accountId=a.accountRefId
inner join purchasebill as c on a.tableDetailId=c.purchaseBillID
 where a.accountRefId=accountId and a.companyRefId=CompanyId and a.accountYearRefId=accountYearId and a.tableReference=3
and a.accountDate BETWEEN FromDate and ToDate and c.purchaseBillType=3 

UNION

select b.accountId,b.accountName as accountname,'1' as 'tableid',accountTransactionId as 'uniqueid',a.accountDate as accountdate,d.`name` 
as 'description1',concat('Cash purchase invoice Number - ',purchaseBillDisplayNumber) as 'description2',
'1' as 'displayorder','' as 'debit', round(amount,2) as 'credit',purchaseBillDisplayNumber as 'innerdisplayorder','3' as 'totaldisplayorder'
 from accounttransaction as a 
inner join account as b on b.accountId=a.accountRefId
inner join purchasebill as c on a.tableDetailId=c.purchaseBillID
inner join customer as d on d.customerID=c.CustomerID
 where a.accountRefId=accountId and a.companyRefId=CompanyId and a.accountYearRefId=accountYearId and a.tableReference=3
and a.accountDate BETWEEN FromDate and ToDate and c.purchaseBillType=2 


UNION

select b.accountId,b.accountName as accountname,'1' as 'tableid',accountTransactionId as 'uniqueid',a.accountDate as accountdate,d.`name` 
as 'description1',concat('Advance amount as per Invoice No - ',purchaseBillDisplayNumber) as 'description2',
'3' as 'displayorder','' as 'debit', round(amount,2) as 'credit','' as 'innerdisplayorder','1' as 'totaldisplayorder'
 from accounttransaction as a 
inner join account as b on b.accountId=a.accountRefId
inner join purchasebill as c on a.tableDetailId=c.purchaseBillID
inner join customer as d on d.customerID=c.CustomerID
 where a.accountRefId=accountId and a.companyRefId=CompanyId and a.accountYearRefId=accountYearId and a.tableReference=3
and a.accountDate BETWEEN FromDate and ToDate and c.purchaseBillType=1



UNION

select b.accountId,b.accountName as accountname,'1' as 'tableid',accountTransactionId as 'uniqueid',a.accountDate as accountdate, e.`name` 
as 'description1',concat('For Invoice No - ',purchaseBillDisplayNumber,'(',c.modeDescription,')') as 'description2',
'1' as 'displayorder','' as 'debit', round(amount,2) as 'credit','' as 'innerdisplayorder','4' as 'totaldisplayorder'
 from accounttransaction as a 
inner join account as b on b.accountId=a.accountRefId
inner join purchasepayment as c on a.tableDetailId=c.purchasePaymentId
