-- ----------------------------
-- Procedure structure for `bank_Account_Transaction`
-- ----------------------------
DROP PROCEDURE IF EXISTS `bank_Account_Transaction`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `bank_Account_Transaction`(IN `FromDate` date,IN `ToDate` date,IN `CompanyId` bigint,IN `accountYearId` bigint,IN `accountId` bigint)
BEGIN
SELECT a.accountTransactionId,a.accountDate as 'accountdate',
CASE b.salesBillType
  WHEN '2' THEN CONCAT(' Cash Sales  as  Per (Bill Number : ',b.salesBillDisplayNumber,')')
  ELSE CONCAT(' Advance for Sales as  Per (Bill Number : ',b.salesBillDisplayNumber,')')
  END  as 'Description1',

CASE a.transactionType
  WHEN '1' THEN a.amount
  ELSE NULL
  END as 'credit'
,
CASE a.transactionType
  WHEN '2' THEN a.amount
  ELSE NULL
  END as 'debit'
 FROM
accounttransaction as a
inner join salesbill as b on b.salesBillID=a.tableDetailId
where a.tableReference=1  and a.transactionType=1
and a.accountDate between FromDate AND ToDate AND a.companyRefId=CompanyId
and a.accountYearRefId=accountYearId and a.accountRefId=accountId
union
SELECT a.accountTransactionId,a.accountDate as 'accountdate',
CASE b.salesBillRefId  WHEN '0' THEN
        CASE b.paymentMode
                        WHEN '1' THEN
                                                                                        CONCAT(' Sales Payment By ',d.`name`,' for the (Bill Number : ',b.billDescription ,') By Cash as per (Receipt Number : (',b.receiptNumber,')' )
                        WHEN '2' THEN
                                                                                        CONCAT(' Sales Payment By ',d.`name`,' for the (Bill Number : ',b.billDescription ,') Through Online (', b.modeDescription ,')' )
                                WHEN '3' THEN
                                                                                        CONCAT(' Sales Payment By ',d.`name`,' for the (Bill Number : ',b.billDescription ,') Through Online (', b.modeDescription ,')' )

                        WHEN '4' THEN
                                                                                        CONCAT(' Sales Payment By ',d.`name`,' for the (Bill Number : ',b.billDescription ,') By Demand Draft (', b.modeDescription ,')' )
        END
ELSE
CASE b.paymentMode
                        WHEN '1' THEN
                                                                CASE c.salesBillType
