-- ----------------------------
-- Procedure structure for `journal_Transaction`
-- ----------------------------
DROP PROCEDURE IF EXISTS `journal_Transaction`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `journal_Transaction`(IN `FromDate` date,IN `ToDate` date,IN `companyRefIdInput` bigint,IN `accountYearRefIdInput` bigint)
Begin
select '1' as 'tableid',salesbillid as 'uniqueid',salesBillDate as accountdate,'Sales Account - Credit' as 'description1',
concat('As Per Bill No:',salesBillDisplayNumber) 
as 'description2','1' as 'displayorder',
'' as 'debit',
round(runningTotal+roundOff,2) as 'credit',salesBillNumber as 'innerdisplayorder','1' as 'totaldisplayorder'

 from salesbill where salesBillType=1 and companyRefId=companyRefIdInput and accountYearRefId=accountYearRefIdInput and salesBillDate BETWEEN FromDate and ToDate


UNION

select '1' as 'tableid',salesbillid as 'uniqueid',salesBillDate as accountdate,'sgst tax' as 'description1',concat('As Per Bill No:',salesBillDisplayNumber) as 'description2','2' as 'displayorder',
'' as 'debit',
round(sgstTotal,2) as 'credit',salesBillNumber as 'innerdisplayorder','1' as 'totaldisplayorder'
 from salesbill where salesBillType=1 and sgstTotal!=0 and companyRefId=companyRefIdInput and accountYearRefId=accountYearRefIdInput and salesBillDate BETWEEN FromDate and ToDate

UNION

select '1' as 'tableid',salesbillid as 'uniqueid',salesBillDate as accountdate,'cgst tax' as 'description1',concat('As Per Bill No:',salesBillDisplayNumber) as 'description2','3' as 'displayorder',
'' as 'debit',
round(cgstTotal,2) as 'credit',salesBillNumber as 'innerdisplayorder','1' as 'totaldisplayorder'
 from salesbill where salesBillType=1 and cgstTotal!=0 and companyRefId=companyRefIdInput and accountYearRefId=accountYearRefIdInput and salesBillDate BETWEEN FromDate and ToDate

UNION

select '1' as 'tableid',salesbillid as 'uniqueid',salesBillDate as accountdate,'igst tax' as 'description1',concat('As Per Bill No:',salesBillDisplayNumber) as 'description2','4' as 'displayorder',
'' as 'debit',
round(igstTotal,2) as 'credit',salesBillNumber as 'innerdisplayorder','1' as 'totaldisplayorder'
 from salesbill where salesBillType=1 and igstTotal!=0 and companyRefId=companyRefIdInput and accountYearRefId=accountYearRefIdInput and salesBillDate BETWEEN FromDate and ToDate


UNION

select '1' as 'tableid',salesbillid as 'uniqueid',salesBillDate as accountdate,'CST tax' as 'description1',concat('As Per Bill No:',salesBillDisplayNumber) as 'description2','5' as 'displayorder',
'' as 'debit',
round(cstTotal,2) as 'credit',salesBillNumber as 'innerdisplayorder','1' as 'totaldisplayorder'
 from salesbill where salesBillType=1 and cstTotal!=0 and companyRefId=companyRefIdInput and accountYearRefId=accountYearRefIdInput and 
salesBillDate BETWEEN FromDate and ToDate and vatCstFlag=1

UNION

select '1' as 'tableid',salesbillid as 'uniqueid',salesBillDate as accountdate,'VAT tax' as 'description1',concat('As Per Bill No:',salesBillDisplayNumber) as 'description2','6' as 'displayorder',
'' as 'debit',
round(vatTotal,2) as 'credit',salesBillNumber as 'innerdisplayorder','1' as 'totaldisplayorder'
 from salesbill where salesBillType=1 and vatTotal!=0 and companyRefId=companyRefIdInput and accountYearRefId=accountYearRefIdInput and salesBillDate 
BETWEEN FromDate and ToDate  and vatCstFlag=1





UNION



select '1' as 'tableid',salesbillid as 'uniqueid',salesBillDate as accountdate,concat(b.`name`,'-',d.cityName)
 as 'description1',concat(' As Per Bill No:',salesBillDisplayNumber) as 'description2','7' as 'displayorder',
round(salesBillTotal,2) as 'debit',
'' as 'credit',salesBillNumber as 'innerdisplayorder','1' as 'totaldisplayorder'
 from salesbill as a 
inner JOIN customer as b on a.CustomerID=b.customerID
inner join customeraddress as c on b.customerID=c.customerRefId and c.activeFlag=1
inner join city as d on d.cityId=c.cityRefId
where salesBillType=1 and a.companyRefId=companyRefIdInput and a.accountYearRefId=accountYearRefIdInput and a.salesBillDate BETWEEN FromDate and ToDate




UNION
select '1' as 'tableid',salesbillid as 'uniqueid',salesBillDate as accountdate,'Cash receieved' as 'description1',
concat('For Bill No:',salesBillDisplayNumber) as 'description2','8' as 'displayorder',
round(salesBillTotal,2) as 'debit','' as 'credit',salesBillNumber as 'innerdisplayorder','1' as 'totaldisplayorder'
from salesbill where (salesBillType=2 or salesBillType=3) 

and companyRefId=companyRefIdInput and accountYearRefId=accountYearRefIdInput and salesBillDate BETWEEN FromDate and ToDate


UNION

select '3' as 'tableid',purchasebillid as 'uniqueid',purchaseBillDate as accountdate,'Credit purchase' as 'description1',
concat('As Per Bill No:',purchaseBillDisplayNumber) as 'description2','1' as 'displayorder',
round(runningTotal+roundOff,2) as 'debit','' as 'credit',purchaseBillDisplayNumber as 'innerdisplayorder','2' as 'totaldisplayorder'

 from purchasebill where purchaseBillType=1 and companyRefId=companyRefIdInput and accountYearRefId=accountYearRefIdInput and purchaseBillDate BETWEEN FromDate and ToDate


UNION

select '3' as 'tableid',purchasebillid as 'uniqueid',purchaseBillDate as accountdate,'sgst tax' as 'description1',concat('As Per Bill No:',purchaseBillDisplayNumber) as 'description2','2' as 'displayorder',

round(sgstTotal,2) as 'debit','' as 'credit',purchaseBillDisplayNumber as 'innerdisplayorder','2' as 'totaldisplayorder'
